package org.springframework.samples.petclinic.acceptance;

import static org.hamcrest.Matchers.containsInAnyOrder;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.node.ObjectNode;

class RequiredOwnerFieldsTest extends AcceptanceBase {

	@Test
	void rejectsBlankAddressThatPassesSchemaValidation() throws Exception {
		ObjectNode o = ownerNode();
		o.put("address", "   ");
		createOwner(o).andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.errors").value(containsInAnyOrder("address")));
	}

	@Test
	void listsEveryMissingOrBlankField() throws Exception {
		ObjectNode o = ownerNode();
		o.remove("firstName");
		o.put("lastName", "");
		o.put("city", " ");
		o.put("telephone", "   ");
		createOwner(o).andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.errors").value(containsInAnyOrder("firstName", "lastName", "city", "telephone")));
	}
}
